<template>
  <div><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><section v-if="showForm" class="panel" style="margin-bottom:16px"><form class="grid-two" @submit.prevent="create"><div class="form-field"><label>Email</label><input v-model.trim="form.email" class="form-input" type="email" required /></div><div class="form-field"><label>Tên hiển thị</label><input v-model.trim="form.displayName" class="form-input" required /></div><div class="form-field"><label>Mật khẩu tạm</label><input v-model="form.password" class="form-input" type="password" minlength="12" required /><span class="cell-subtle">Tối thiểu 12 ký tự</span></div><div class="form-field"><label>Vai trò</label><select v-model="form.role" class="form-select" required><option value="">Chọn vai trò</option><option v-for="role in roles" :key="role.id" :value="role.name">{{ role.name }}</option></select></div><button class="button primary" :disabled="busy">Tạo tài khoản</button></form></section><section class="panel"><div class="toolbar page-toolbar"><input v-model="query" class="search-input" placeholder="Tìm người dùng…" /><div class="toolbar-actions"><span class="cell-subtle">{{ filtered.length }} tài khoản</span><button class="button primary" @click="showForm = !showForm">{{ showForm ? 'Đóng biểu mẫu' : 'Tạo người dùng' }}</button></div></div><div v-if="loading" class="loading-state">Đang tải người dùng…</div><div v-else-if="filtered.length" class="table-wrap"><table class="data-table"><thead><tr><th>Tài khoản</th><th>Email</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="user in filtered" :key="user.id"><td><span class="cell-primary">{{ user.displayName }}</span><span class="cell-subtle">{{ user.id.slice(0, 8) }}</span></td><td>{{ user.email }}</td><td><StatusPill :value="statusLabel(user)" :tone="isActive(user) ? 'success' : 'muted'" /></td><td><button class="mini-button" @click="toggle(user)">{{ isActive(user) ? 'Vô hiệu hóa' : 'Kích hoạt' }}</button></td></tr></tbody></table></div><div v-else class="empty-state"><strong>Chưa có tài khoản</strong><span>Tạo tài khoản theo vai trò đã được cấp.</span></div></section></div>
</template>
<script setup lang="ts">
import { errorMessage } from '../../../shared/api/http'
import { computed, onMounted, reactive, ref } from 'vue'; import StatusPill from '../../../shared/ui/StatusPill.vue'; import { identityApi } from '../../../shared/api/client'; import type { Account } from '../../../shared/types'
const users = ref<Account[]>([]); const roles = ref<{ id: string; name: string; permissions: string[] }[]>([]); const query = ref(''); const loading = ref(true); const busy = ref(false); const showForm = ref(false); const error = ref(''); const form = reactive({ email: '', displayName: '', password: '', role: '' }); const filtered = computed(() => users.value.filter(item => `${item.displayName} ${item.email}`.toLowerCase().includes(query.value.toLowerCase()))); function isActive(item: Account) { return item.status === 0 || String(item.status).toLowerCase() === 'active' } function statusLabel(item: Account) { return isActive(item) ? 'Đang hoạt động' : 'Đã vô hiệu hóa' }
async function load() { loading.value = true; error.value = ''; try { const result = await Promise.all([identityApi.users(), identityApi.roles()]); users.value = result[0]; roles.value = result[1] } catch (cause) { error.value = errorMessage(cause) || 'Không tải được người dùng.' } finally { loading.value = false } }; async function create() { busy.value = true; try { const user = await identityApi.createUser({ email: form.email, displayName: form.displayName, password: form.password, roles: [form.role] }); users.value.unshift(user); showForm.value = false; form.email = ''; form.displayName = ''; form.password = ''; form.role = '' } catch (cause) { error.value = errorMessage(cause) || 'Không tạo được người dùng.' } finally { busy.value = false } }; async function toggle(user: Account) { const wasActive = isActive(user); try { if (wasActive) await identityApi.disableUser(user.id); else await identityApi.enableUser(user.id); user.status = wasActive ? 'Disabled' : 'Active' } catch (cause) { error.value = errorMessage(cause) || 'Không cập nhật được tài khoản.' } }; onMounted(load)
</script>
